 batch jsonb := $batch$[{"record": {"content_id": "c0e7ec08-13f5-52f3-9dd8-a78c670a56ed", "content_type": "QUICK_LEARN", "title": "Shared Fryers", "subtitle": "The potato isn't the only thing to check.", "domain": "KNOW", "topic": null, "interaction_type": "KNOWLEDGE", "difficulty": null, "estimated_minutes": 2, "intro": null, "content_body": {"format": "quick_learn_v1", "content_id": "QL_002", "cards": [{"title": "1 | Fries can be tricky", "body": "Plain potatoes are naturally gluten-free. But restaurant fries may be cooked in the same oil as breaded foods or other foods containing gluten."}, {"title": "2 | Ask one high-value question", "body": "Try: “Are the fries cooked in a dedicated gluten-free fryer?” You can also ask whether the fries themselves have any coating or seasoning that needs checking."}, {"title": "3 | Don't make a universal rule", "body": "Not every restaurant fryer setup is the same. Get the information for the place you're actually at."}], "related_practice_id": "PRACTICE_001", "source_evidence": "Celiac Disease Foundation — Dining and Social Eating", "expert_reviewed": false, "original_metadata": {"content_id": "QL_002", "content_type": "QUICK_LEARN", "domain": "KNOW", "subtitle": "The potato isn't the only thing to check.", "estimated_minutes": "1–2 min", "xp_value": "+5", "related_practice_id": "PRACTICE_001", "review_status": "approved_for_build", "expert_reviewed": "not required for coding", "medical_review_required": "false", "content_version": "1.0", "active": "true", "title": "Shared Fryers", "source_type": null, "key_takeaway": "For fried food, check the food and the fryer.", "try_this": "Save this question: “Is there a dedicated fryer for the gluten-free food?”", "source_evidence": "Celiac Disease Foundation — Dining and Social Eating", "related_practice": "PRACTICE_001 — Are the Fries Really Gluten-Free?", "source_url": "https://celiac.org/dining-and-social-eating/", "review_note": null, "clinical_safety_note": null}}, "choices": [], "feedback": {}, "teaching_point": "For fried food, check the food and the fryer.", "next_step": "Save this question: “Is there a dedicated fryer for the gluten-free food?”", "related_content_ids": ["155cbeba-df91-574e-9cc4-de5e31c7fd78"], "xp_value": 5, "source_type": "EDITORIAL", "source_organization": "Celiac Disease Foundation", "source_title": "Dining and Social Eating", "source_url": "https://celiac.org/dining-and-social-eating/", "author": null, "review_status": "APPROVED", "expert_reviewer": null, "medical_review_required": false, "content_version": 1, "last_reviewed": null, "active": true}, "placeholder": {"content_id": "c0e7ec08-13f5-52f3-9dd8-a78c670a56ed", "content_type": "QUICK_LEARN", "title": "QL_002 Shared Fryers", "subtitle": null, "domain": null, "topic": null, "interaction_type": "KNOWLEDGE", "difficulty": null, "estimated_minutes": null, "intro": null, "content_body": [], "choices": [], "feedback": {}, "teaching_point": null, "next_step": null, "related_content_ids": [], "xp_value": 0, "source_type": "EDITORIAL", "source_organization": null, "source_title": null, "source_url": null, "author": null, "review_status": "DRAFT", "expert_reviewer": null, "medical_review_required": true, "content_version": 1, "last_reviewed": null, "active": false}}, {"record": {"content_id": "b89f6056-96ac-5248-8bf1-c85369e3cad8", "content_type": "QUICK_LEARN", "title": "Reading a Food Label", "subtitle": "Use a process instead of guessing.", "domain": "KNOW", "topic": null, "interaction_type": "KNOWLEDGE", "difficulty": null, "estimated_minutes": 3, "intro": null, "content_body": {"format": "quick_learn_v1", "content_id": "QL_003", "cards": [{"title": "1 | Start with the label", "body": "Check the package for a gluten-free claim and read the ingredient information. In the U.S., “gluten-free” is a voluntary claim, but foods using it under FDA rules must meet the federal definition."}, {"title": "2 | Know the major grains", "body": "Gluten occurs naturally in wheat, barley, rye, and their crossbred hybrids such as triticale. Ingredients derived from gluten-containing grains can also require attention."}, {"title": "3 | Unknown doesn't mean unsafe—or safe", "body": "If you cannot tell whether an ingredient or product works for your gluten-free diet, don't guess from the name. Look for reliable information, such as the manufacturer or another trusted source."}], "related_practice_id": "PRACTICE_003", "source_evidence": "FDA — Gluten and Food Labeling; NIDDK", "expert_reviewed": false, "original_metadata": {"content_id": "QL_003", "content_type": "QUICK_LEARN", "domain": "KNOW", "subtitle": "Use a process instead of guessing.", "estimated_minutes": "3 min", "xp_value": "+5", "related_practice_id": "PRACTICE_003", "review_status": "approved_for_build", "expert_reviewed": "not required for coding", "medical_review_required": "false", "content_version": "1.0", "active": "true", "title": "Reading a Food Label", "source_type": null, "key_takeaway": "Use a repeatable label-checking process. Don't guess.", "try_this": "When a product is unfamiliar, practice saying: “I need more information” instead of forcing a yes/no answer.", "source_evidence": "FDA — Gluten and Food Labeling; NIDDK", "related_practice": "PRACTICE_003 — Label Detective", "source_url": "https://www.fda.gov/food/nutrition-education-resources-materials/gluten-and-food-labeling", "review_note": null, "clinical_safety_note": null}}, "choices": [], "feedback": {}, "teaching_point": "Use a repeatable label-checking process. Don't guess.", "next_step": "When a product is unfamiliar, practice saying: “I need more information” instead of forcing a yes/no answer.", "related_content_ids": ["4cab56b8-ea49-5204-9dc2-f03df42ab0e5"], "xp_value": 5, "source_type": "EDITORIAL", "source_organization": "FDA", "source_title": "Gluten and Food Labeling; NIDDK", "source_url": "https://www.fda.gov/food/nutrition-education-resources-materials/gluten-and-food-labeling", "author": null, "review_status": "APPROVED", "expert_reviewer": null, "medical_review_required": false, "content_version": 1, "last_reviewed": null, "active": true}, "placeholder": {"content_id": "b89f6056-96ac-5248-8bf1-c85369e3cad8", "content_type": "QUICK_LEARN", "title": "QL_003 Reading a Food Label", "subtitle": null, "domain": null, "topic": null, "interaction_type": "KNOWLEDGE", "difficulty": null, "estimated_minutes": null, "intro": null, "content_body": [], "choices": [], "feedback": {}, "teaching_point": null, "next_step": null, "related_content_ids": [], "xp_value": 0, "source_type": "EDITORIAL", "source_organization": null, "source_title": null, "source_url": null, "author": null, "review_status": "DRAFT", "expert_reviewer": null, "medical_review_required": true, "content_version": 1, "last_reviewed": null, "active": false}}, {"record": {"content_id": "14ba7cf7-5bfa-55cc-871f-64cf0f0b3b90", "content_type": "QUICK_LEARN", "title": "Naturally GF vs. Prepared GF", "subtitle": "A naturally gluten-free food can change once preparation starts.", "domain": "KNOW", "topic": null, "interaction_type": "KNOWLEDGE", "difficulty": null, "estimated_minutes": 2, "intro": null, "content_body": {"format": "quick_learn_v1", "content_id": "QL_004", "cards": [{"title": "1 | Naturally gluten-free", "body": "Many foods are naturally gluten-free, including plain fruits, vegetables, rice, potatoes, meat, and fish."}, {"title": "2 | Prepared food adds questions", "body": "Once a food is seasoned, coated, mixed, cooked, or served with other foods, ingredients and cross-contact may need to be checked."}, {"title": "3 | Use two questions", "body": "Ask: “What is in it?” and “How was it prepared?” Those two questions solve different parts of the puzzle."}], "related_practice_id": "PRACTICE_002", "source_evidence": "NIDDK — Eating, Diet, & Nutrition for Celiac Disease", "expert_reviewed": false, "original_metadata": {"content_id": "QL_004", "content_type": "QUICK_LEARN", "domain": "KNOW", "subtitle": "A naturally gluten-free food can change once preparation starts.", "estimated_minutes": "2 min", "xp_value": "+5", "related_practice_id": "PRACTICE_002", "review_status": "approved_for_build", "expert_reviewed": "not required for coding", "medical_review_required": "false", "content_version": "1.0", "active": "true", "title": "Naturally GF vs. Prepared GF", "source_type": null, "key_takeaway": "Naturally GF describes the food. Preparation describes what happened to it.", "try_this": "Pick one naturally GF food and name two ways preparation could add new questions.", "source_evidence": "NIDDK — Eating, Diet, & Nutrition for Celiac Disease", "related_practice": "PRACTICE_002 — The Gluten-Free Pizza", "source_url": "https://www.niddk.nih.gov/health-information/digestive-diseases/celiac-disease/eating-diet-nutrition", "review_note": null, "clinical_safety_note": null}}, "choices": [], "feedback": {}, "teaching_point": "Naturally GF describes the food. Preparation describes what happened to it.", "next_step": "Pick one naturally GF food and name two ways preparation could add new questions.", "related_content_ids": ["f7e4d7d3-b640-56c1-a6b4-e043bb612326"], "xp_value": 5, "source_type": "EDITORIAL", "source_organization": "NIDDK", "source_title": "Eating, Diet, & Nutrition for Celiac Disease", "source_url": "https://www.niddk.nih.gov/health-information/digestive-diseases/celiac-disease/eating-diet-nutrition", "author": null, "review_status": "APPROVED", "expert_reviewer": null, "medical_review_required": false, "content_version": 1, "last_reviewed": null, "active": true}, "placeholder": {"content_id": "14ba7cf7-5bfa-55cc-871f-64cf0f0b3b90", "content_type": "QUICK_LEARN", "title": "QL_004 Naturally GF vs Prepared GF", "subtitle": null, "domain": null, "topic": null, "interaction_type": "KNOWLEDGE", "difficulty": null, "estimated_minutes": null, "intro": null, "content_body": [], "choices": [], "feedback": {}, "teaching_point": null, "next_step": null, "related_content_ids": [], "xp_value": 0, "source_type": "EDITORIAL", "source_organization": null, "source_title": null, "source_url": null, "author": null, "review_status": "DRAFT", "expert_reviewer": null, "medical_review_required": true, "content_version": 1, "last_reviewed": null, "active": false}}, {"record": {"content_id": "4649245f-7467-554a-917f-c3d1ffa284ec", "content_type": "QUICK_LEARN", "title": "Eating Out: The Questions That Matter", "subtitle": "You don't need 20 questions. Start with the ones that change your decision.", "domain": "MANAGE", "topic": null, "interaction_type": "KNOWLEDGE", "difficulty": null, "estimated_minutes": 3, "intro": null, "content_body": {"format": "quick_learn_v1", "content_id": "QL_005", "cards": [{"title": "1 | Tell them what you need", "body": "Let the server know you have celiac disease and need a gluten-free meal. A clear medical explanation can help staff understand that this is not simply a preference."}, {"title": "2 | Ask about ingredients + preparation", "body": "Useful questions include: What is in the dish? How is it prepared? Is shared oil or equipment used? Is there a separate or cleaned preparation process for gluten-free food?"}, {"title": "3 | Decide from the information you get", "body": "A restaurant conversation cannot guarantee a meal. It can give you information to make your own decision. A backup remains an option."}], "related_practice_id": "PRACTICE_008", "source_evidence": "NIDDK; Beyond Celiac; Celiac Disease Foundation", "expert_reviewed": false, "original_metadata": {"content_id": "QL_005", "content_type": "QUICK_LEARN", "domain": "MANAGE", "subtitle": "You don't need 20 questions. Start with the ones that change your decision.", "estimated_minutes": "3 min", "xp_value": "+5", "related_practice_id": "PRACTICE_008", "review_status": "approved_for_build", "expert_reviewed": "not required for coding", "medical_review_required": "false", "content_version": "1.0", "active": "true", "title": "Eating Out: The Questions That Matter", 