 item jsonb; wanted jsonb; placeholder jsonb; code text;
 incoming public.explore_content%rowtype; current_row public.explore_content%rowtype;
 row_exists boolean;
begin
 for item in select value from jsonb_array_elements(batch) loop
  wanted := item->'record'; placeholder := item->'placeholder'; code := wanted->'content_body'->>'content_id';
  select * into incoming from jsonb_populate_record(null::public.explore_content,wanted);
  if exists(select 1 from public.explore_content where content_body->>'content_id'=code and content_id<>incoming.content_id) then
   raise exception '% already uses a different UUID. Batch rolled back.',code;
  end if;
  if not exists(select 1 from public.explore_content where content_id=incoming.related_content_ids[1] and content_type='PRACTICE_A_SKILL'
    and content_body->>'scenario_id'=incoming.content_body->>'related_practice_id'
    and (content_body->>'scenario_id') || ' — ' || title = incoming.content_body->'original_metadata'->>'related_practice') then
   raise exception '% related Practice mapping is missing or changed. Batch rolled back.',code;
  end if;
  select * into current_row from public.explore_content where content_id=incoming.content_id for update;
  row_exists := found;
  if row_exists and not exists(select 1 from jsonb_each(wanted) f where to_jsonb(current_row)->f.key is distinct from f.value) then continue; end if;
  if row_exists and exists(select 1 from jsonb_each(placeholder) f where to_jsonb(current_row)->f.key is distinct from f.value) then
   raise exception '% has edits beyond its original placeholder. Batch rolled back; review before replacing.',code;
  end if;
  if row_exists then
   update public.explore_content set content_type=incoming.content_type, title=incoming.title, subtitle=incoming.subtitle, domain=incoming.domain, topic=incoming.topic, interaction_type=incoming.interaction_type, difficulty=incoming.difficulty, estimated_minutes=incoming.estimated_minutes, intro=incoming.intro, content_body=incoming.content_body, choices=incoming.choices, feedback=incoming.feedback, teaching_point=incoming.teaching_point, next_step=incoming.next_step, related_content_ids=incoming.related_content_ids, xp_value=incoming.xp_value, source_type=incoming.source_type, source_organization=incoming.source_organization, source_title=incoming.source_title, source_url=incoming.source_url, author=incoming.author, review_status=incoming.review_status, expert_reviewer=incoming.expert_reviewer, medical_review_required=incoming.medical_review_required, content_version=incoming.content_version, last_reviewed=incoming.last_reviewed, active=incoming.active where content_id=incoming.content_id;
  else
   insert into public.explore_content (content_id, content_type, title, subtitle, domain, topic, interaction_type, difficulty, estimated_minutes, intro, content_body, choices, feedback, teaching_point, next_step, related_content_ids, xp_value, source_type, source_organization, source_title, source_url, author, review_status, expert_reviewer, medical_review_required, content_version, last_reviewed, active) values (incoming.content_id, incoming.content_type, incoming.title, incoming.subtitle, incoming.domain, incoming.topic, incoming.interaction_type, incoming.difficulty, incoming.estimated_minutes, incoming.intro, incoming.content_body, incoming.choices, incoming.feedback, incoming.teaching_point, incoming.next_step, incoming.related_content_ids, incoming.xp_value, incoming.source_type, incoming.source_organization, incoming.source_title, incoming.source_url, incoming.author, incoming.review_status, incoming.expert_reviewer, incoming.medical_review_required, incoming.content_version, incoming.last_reviewed, incoming.active);
  end if;
 end loop;
end $import$;
commit;
